-- Insert Quiz Questions for Lesson: Write and Send the Request

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'write-send-request' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson write-send-request not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What kind of review should the message request?', 
    '["A five-star review","An honest review","A positive review only","A detailed review with photos"]'::jsonb,
    'An honest review',
    'The message should request an honest review. Asking for a specific rating or only positive reviews violates fair-review practices and platform rules.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How many main links should a simple request contain?', 
    '["One main link","Two links for backup","Three or more options","No links, just instructions"]'::jsonb,
    'One main link',
    'A simple request should contain one main link to avoid confusion and make it easy for the customer to take action.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where can an individual request be sent and tracked?', 
    '["Reputation → Overview","Reputation → Requests","Settings → Review Link","Automation → Workflows"]'::jsonb,
    'Reputation → Requests',
    'Individual review requests are sent and tracked in Reputation → Requests, where you can see status, delivery, and responses.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


