-- Insert Quiz Questions for Lesson: Track Requests and Fix Failures

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'track-requests-fix-failures' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson track-requests-fix-failures not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does ''Failed'' tell you?', 
    '["The customer ignored the message.","The request could not be delivered.","The request is still queued.","The review was negative."]'::jsonb,
    'The request could not be delivered.',
    '''Failed'' means the message could not be delivered. Check the email address, phone number, sender settings, and connection to fix the issue.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Name two contact details that may cause a request failure.', 
    '["The email address and phone number.","The customer''s name and address.","The business name and location.","The review platform and widget settings."]'::jsonb,
    'The email address and phone number.',
    'Incorrect or missing email addresses and phone numbers are the most common causes of request delivery failures.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you avoid sending another request immediately when the first one shows Sent?', 
    '["The customer may already have received it and needs reasonable time to respond.","LeadProspectrr does not allow multiple requests.","It will cost extra credits.","The first request will be cancelled."]'::jsonb,
    'The customer may already have received it and needs reasonable time to respond.',
    'When a request shows Sent, the customer may already have received it. Give them reasonable time to respond before sending a follow-up.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


